    assert Enum.any?(optimizer_count_report["errors"], &(&1["path"] == "$.candidate_count"))

    assert {:ok, %{"schema_contract" => "ranking_comparison_report.v1"}} =
             Schema.validate_artifact(ranking_comparison_report)

