    assert {:error, invalid_manifest_target_id_report} =
             Schema.validate_artifact(invalid_manifest_target_id)

    assert Enum.any?(
             invalid_manifest_target_id_report["errors"],
             &(&1["path"] == "$.rows[0].target_id")
           )

    invalid_manifest_review_branch_counts =
      put_in(
